// src/workers/d1/entry.worker.ts
import { WorkerEntrypoint } from "cloudflare:workers";

// src/workers/shared/constants.ts
var SharedHeaders = {
  LOG_LEVEL: "MF-Log-Level",
  NAMESPACE: "MF-Namespace"
}, SharedBindings = {
  TEXT_NAMESPACE: "MINIFLARE_NAMESPACE",
  DURABLE_OBJECT_NAMESPACE_OBJECT: "MINIFLARE_OBJECT",
  MAYBE_SERVICE_BLOBS: "MINIFLARE_BLOBS",
  MAYBE_SERVICE_LOOPBACK: "MINIFLARE_LOOPBACK",
  MAYBE_JSON_ENABLE_CONTROL_ENDPOINTS: "MINIFLARE_ENABLE_CONTROL_ENDPOINTS"
};

// src/workers/d1/export.ts
import { z as z2 } from "miniflare:zod";

// src/workers/d1/schemas.ts
import { z } from "miniflare:zod";
var D1_SESSION_COMMIT_TOKEN_HTTP_HEADER = "x-cf-d1-session-commit-token", D1ValueSchema = z.union([
  z.number(),
  z.string(),
  z.null(),
  z.number().array()
]), D1QuerySchema = z.object({
  sql: z.string(),
  params: z.array(D1ValueSchema).nullable().optional()
}), D1QueriesSchema = z.union([D1QuerySchema, z.array(D1QuerySchema)]), D1RpcRequestSchema = z.object({
  queries: z.array(D1QuerySchema),
  bookmark: z.string().optional()
}), D1MetaSchema = z.object({
  served_by: z.string(),
  served_by_primary: z.boolean().optional(),
  served_by_region: z.string().optional(),
  served_by_colo: z.string().optional(),
  timings: z.object({ sql_duration_ms: z.number() }).optional(),
  duration: z.number(),
  changes: z.number(),
  last_row_id: z.number(),
  changed_db: z.boolean(),
  size_after: z.number(),
  rows_read: z.number(),
  rows_written: z.number(),
  total_attempts: z.number().optional()
}), D1RowsAndColumnsSchema = z.object({
  columns: z.array(z.string()),
  rows: z.array(z.array(D1ValueSchema))
}), D1RowsAndColumnsSuccessSchema = z.object({
  success: z.literal(!0),
  results: D1RowsAndColumnsSchema,
  meta: D1MetaSchema
}), D1FailureResponseSchema = z.object({
  success: z.literal(!1),
  error: z.string()
}), D1RowsAndColumnsResponseSchema = z.union([
  z.array(D1RowsAndColumnsSuccessSchema),
  D1FailureResponseSchema
]);

// src/workers/d1/export.ts
var D1_EXPORT_PRAGMA = "PRAGMA miniflare_d1_export(?,?,?);";
function isD1ExportPragma(queries) {
  return queries.length === 1 && queries[0].sql === D1_EXPORT_PRAGMA && (queries[0].params?.length || 0) >= 2;
}
var D1ExportMetaSchema = z2.record(z2.string(), z2.never()), D1ExportResponseSchema = z2.union([
  z2.object({
    success: z2.literal(!0),
    results: z2.tuple([z2.array(z2.string())]),
    meta: D1ExportMetaSchema
  }),
  D1FailureResponseSchema
]);
function parseD1RpcExportResponse(input) {
  let body = D1ExportResponseSchema.parse(input);
  if (!body.success) {
    let error = new Error(body.error);
    throw error.name = "D1_ERROR", error;
  }
  return {
    results: [
      {
        meta: body.meta,
        data: {
          kind: "raw",
          // The HTTP wrapper exposes the export row's array indices
          // as column names; preserve that convention over RPC.
          columns: body.results[0].map((_, index) => String(index)),
          rows: body.results
        }
      }
    ]
  };
}

// src/workers/d1/entry.worker.ts
var D1Entry = class extends WorkerEntrypoint {
  /** Preserves the HTTP protocol used by bindings without the RPC flag. */
  async fetch(request) {
    let requestNamespace = request.headers.get(SharedHeaders.NAMESPACE), name = this.ctx.props[SharedBindings.TEXT_NAMESPACE] ?? this.env[SharedBindings.TEXT_NAMESPACE] ?? requestNamespace;
    if (name === null)
      throw new Error(
        "D1 entry worker: no database ID provided via props, binding, or request header"
      );
    let namespace = this.env[SharedBindings.DURABLE_OBJECT_NAMESPACE_OBJECT], stub = namespace.get(namespace.idFromName(name));
    if (requestNamespace !== null) {
      let headers = new Headers(request.headers);
      headers.delete(SharedHeaders.NAMESPACE), request = new Request(request, { headers });
    }
    return await stub.fetch(request, { cf: { miniflare: { name } } });
  }
  /** Returns raw transactional results; query failures are thrown over RPC. */
  async query(request) {
    let { queries, bookmark } = D1RpcRequestSchema.parse(request), headers = new Headers({ "Content-Type": "application/json" });
    bookmark && headers.set(D1_SESSION_COMMIT_TOKEN_HTTP_HEADER, bookmark);
    let response = await this.fetch(
      new Request("http://d1/query?resultsFormat=ROWS_AND_COLUMNS", {
        method: "POST",
        headers,
        body: JSON.stringify(queries)
      })
    ), responseBody = await response.json();
    if (isD1ExportPragma(queries))
      return parseD1RpcExportResponse(responseBody);
    let body = D1RowsAndColumnsResponseSchema.parse(responseBody);
    if (!Array.isArray(body)) {
      let error = new Error(body.error);
      throw error.name = "D1_ERROR", error;
    }
    let result = {
      results: body.map(({ meta, results }) => ({
        meta,
        data: { kind: "raw", ...results }
      }))
    }, responseBookmark = response.headers.get(
      D1_SESSION_COMMIT_TOKEN_HTTP_HEADER
    );
    return responseBookmark && (result.bookmark = responseBookmark), result;
  }
};
export {
  D1Entry as default
};
